def check_for_n_alternative(n_target, max_z, max_k):
    for z in range(1, max_z):
        y1 = z*z + 1
        # Now y1 is a valid y1.
        # y2 can be anything such that y2^2 - 2y2 + 2 is divisible by y1.
        # One such y2 is z + 1.
