def check_for_n_final(n_target, max_y1):
    for y1 in range(2, max_y1):
        # Find z such that z^2 = -1 mod y1
        # z^2 + 1 = k*y1
        # This means all prime factors of y1 are 2 or 4k+1.
        z_vals = []
        for z in range(y1 // 2 + 1):
            if (z*z + 1) % y1 == 0:
                z_vals.append(z)
                z_vals.append(y1 - z)

        for z in z_vals:
            # y2 = k*y1 + z + 1
            # We can't check all k, but maybe k up to 1000 is enough
            for k in range(0, 1000):
                y2 = k * y1 + z + 1
