def search_by_y3(max_y3):
    for y3 in range(2, max_y3):
        num = y3**2 - 2*y3 + 2
        # Find divisors of num
        divs = []
        for i in range(1, int(num**0.5) + 1):
            if num % i == 0:
                divs.append(i)
                divs.append(num // i)

        for y2 in divs:
            if y2 < 2: continue
            y4 = num // y2
            if y4 < 2: continue

            # Now check y1 and y5
            num1 = y2**2 - 2*y2 + 2
            if num1 % y3 == 0:
                y1 = num1 // y3
                if y1 >= 2:
                    num5 = y4**2 - 2*y4 + 2
                    if num5 % y3 == 0:
                        y5 = num5 // y3
                        if y5 >= 2:
                            return True, [y1, y2, y3, y4, y5]
    return False, None

